import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { parse } from '@babel/parser';

/** Normalize generated comments without changing strings or template literals. */
export function formatDesignSystemBundle(source) {
    const comments = parse(source, { sourceType: 'script' }).comments || [];
    for (const comment of comments.toReversed()) {
        const text = source.slice(comment.start, comment.end).replace(/[\t ]+(?=\r?$)/gm, '');
        source = source.slice(0, comment.start) + text + source.slice(comment.end);
    }
    return source;
}

const DESIGN_SYSTEM_SOURCE_FILES = [
    'frontend/design-system/catalogEntry.js',
    'frontend/design-system/catalog.js',
    'frontend/design-system/themeCatalogModel.js',
    'frontend/js/selectCombobox.js',
    'frontend/js/tooltip.js',
    'frontend/js/core/tooltipModel.js',
    'frontend/themes/manifest.json',
];

export function designSystemSourceHash(root) {
    const hash = createHash('sha256');
    for (const file of DESIGN_SYSTEM_SOURCE_FILES) {
        hash.update(file);
        hash.update('\0');
        hash.update(readFileSync(resolve(root, file)));
        hash.update('\0');
    }
    return hash.digest('hex');
}

export function designSystemBundlePath(root) {
    return resolve(root, 'frontend/design-system/catalog.bundle.js');
}

export function designSystemBundleOptions(root) {
    const sourceHash = designSystemSourceHash(root);
    return {
        entryPoints: [resolve(root, 'frontend/design-system/catalogEntry.js')],
        outfile: designSystemBundlePath(root),
        bundle: true,
        write: false,
        format: 'iife',
        platform: 'browser',
        target: 'es2020',
        legalComments: 'none',
        banner: {
            js: `/* Generated by scripts/build-design-system.mjs. Source hash: ${sourceHash}. Do not edit directly. */`,
        },
    };
}
